        var root=new DockPanel{Margin=new(24)};Content=root;var heading=new StackPanel();heading.Children.Add(Ui.Text("完善行程",22,true));heading.Children.Add(Ui.Text("核对活动，选择准确地点，补充时间后计算路线。开始留空表示由系统安排。",12));table=new();foreach(var t in vm.State.Tables)table.Items.Add(new ComboBoxItem{Content=t.Name,Tag=t.Id});table.Items.Add(new ComboBoxItem{Content="＋ 新建行程表",Tag="NEW"});table.SelectedIndex=preferNewTable?table.Items.Count-1:Math.Max(0,vm.State.Tables.FindIndex(t=>t.Id==vm.SelectedTableId));Ui.Field(heading,"保存到行程表",table);newName.Text=(requests.FirstOrDefault()?.Day??Clock.Today).ToString("MM-dd")+" 行程计划";newName.Tag="NewTableName";newColor.Width=340;var newFields=new StackPanel();Ui.Field(newFields,"新行程表名称",newName);newFields.Children.Add(Ui.Text("选择行程表主色",12,true));newFields.Children.Add(newColor);heading.Children.Add(newFields);void TargetChanged()=>newFields.Visibility=(string?)((ComboBoxItem?)table.SelectedItem)?.Tag=="NEW"?Visibility.Visible:Visibility.Collapsed;table.SelectionChanged+=(_,_)=>TargetChanged();TargetChanged();
        var footer=new DockPanel();DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var buttons=Ui.Row(Ui.Button("取消",Close));DockPanel.SetDock(buttons,Dock.Right);footer.Children.Add(buttons);footer.Children.Add(status);var generate=Ui.Button("生成行程 →",()=>{},true);buttons.Children.Add(generate);generate.Click+=async(_,_)=>{if(committed)return;generate.IsEnabled=false;panel.IsEnabled=false;heading.IsEnabled=false;try{await Generate();}catch(OperationCanceledException){if(!closing)status.Text="已取消，可调整后重试。";}catch(Exception ex){if(!closing)status.Text=ex.Message;}finally{if(!closing&&!committed){generate.IsEnabled=true;panel.IsEnabled=true;heading.IsEnabled=true;}}};
