        bool syncing=false;
        void FinishByDuration(){if(syncing)return;try{syncing=true;if(int.TryParse(card.Duration.Text,out var minutes)&&minutes>=0&&Minute(card.Begin.Text) is {} start&&card.Day.SelectedDate is {} d){var last=d.Date.AddMinutes(start+minutes);card.End.DateContext=last.Date;card.EndDay.SelectedDate=last.Date;card.End.Text=last.ToString("HH:mm");}}catch(ArgumentException){}finally{syncing=false;}}
        void BeginChanged(){if(syncing)return;try{syncing=true;card.Day.SelectedDate=card.Begin.DateContext.Date;}finally{syncing=false;}FinishByDuration();}
        void EndChanged(){if(syncing)return;try{syncing=true;card.EndDay.SelectedDate=card.End.DateContext.Date;if(Minute(card.Begin.Text) is {} start&&Minute(card.End.Text) is {} end&&card.Day.SelectedDate is {} d){int minutes=(int)(card.End.DateContext.Date-d.Date).TotalMinutes+end-start;if(minutes>=0)card.Duration.Text=minutes.ToString();}}catch(ArgumentException){}finally{syncing=false;}}
        card.Duration.TextChanged+=(_,_)=>FinishByDuration();card.Begin.Changed+=BeginChanged;card.Begin.DateTimeChanged+=_=>BeginChanged();card.End.Changed+=EndChanged;card.End.DateTimeChanged+=_=>EndChanged();card.Day.SelectedDateChanged+=(_,_)=>{if(syncing)return;if(card.Day.SelectedDate is {} d)card.Begin.DateContext=d.Date;FinishByDuration();};card.EndDay.SelectedDateChanged+=(_,_)=>{if(syncing)return;if(card.EndDay.SelectedDate is {} d)card.End.DateContext=d.Date;EndChanged();};
        var quick=new WrapPanel();foreach(int duration in new[]{30,60,90,120})quick.Children.Add(Ui.Button(duration+"分钟",()=>card.Duration.Text=duration.ToString()));p.Children.Add(quick);
        Ui.Field(p,"地点关键词",card.Query);var search=Ui.Button("搜索地点",()=>{});p.Children.Add(search);Ui.Field(p,"准确地点",card.Places);p.Children.Add(card.Status);
        card.Query.TextChanged+=(_,_)=>{card.Chosen=null;card.Places.ItemsSource=null;card.Status.Text="地点已改动，请重新搜索并选择。";};card.Places.SelectionChanged+=(_,_)=>{card.Chosen=card.Places.SelectedItem as Place;if(card.Chosen is {} chosen)card.Status.Text=chosen.Source??"已选择";};
        search.Click+=async(_,_)=>{search.IsEnabled=false;string query=card.Query.Text;try{var found=await map.SearchAsync(query,cancel.Token);if(!closing&&query==card.Query.Text){card.Places.ItemsSource=found;card.Places.SelectedIndex=found.Count==1?0:-1;card.Status.Text=found.Count==1?found[0].Source??"已选地点":"请选择准确地点";}}catch(OperationCanceledException){}catch(Exception ex){if(!closing)card.Status.Text=ex.Message;}finally{if(!closing)search.IsEnabled=true;}};
        Ui.Field(p,"前往此处",card.Mode);card.Note.AcceptsReturn=true;card.Note.TextWrapping=TextWrapping.Wrap;card.Note.MinHeight=70;Ui.Field(p,"备注",card.Note);p.Children.Add(card.Reminder);Ui.Field(p,"提前分钟",card.Lead);
        if(index>0){var compare=Ui.Button("比较与上一项之间的交通",()=>{});p.Children.Add(compare);compare.Click+=async(_,_)=>{compare.IsEnabled=false;try{var before=cards[index-1].Chosen??throw new ArgumentException("请先选择上一项地点。");var here=card.Chosen??throw new ArgumentException("请先选择此项地点。");var estimate=await RepositoryDialogs.Travel(this,map,before,here,null,(card.Day.SelectedDate??Clock.Now).Date,cancel.Token);card.Mode.SelectedItem=estimate.Source.Split(" · ")[0];card.Status.Text=$"{estimate.Source} · 约{estimate.Minutes}分钟";}catch(OperationCanceledException){}catch(Exception ex){if(!closing)card.Status.Text=ex.Message;}finally{if(!closing)compare.IsEnabled=true;}};}
        cards.Add(card);panel.Children.Add(Ui.Card(p));
    }
    static string ClockText(int? minute)=>minute is {} m?$"{(m/60)%24:00}:{m%60:00}":"";
    async Task ResolvePlacesAsync()
    {
        foreach(var c in cards){cancel.Token.ThrowIfCancellationRequested();string query=c.Query.Text;if(string.IsNullOrWhiteSpace(query)||c.Chosen is not null)continue;c.Status.Text="正在核对地点…";try{var found=await map.SearchAsync(query,cancel.Token);if(closing||query!=c.Query.Text)continue;c.Places.ItemsSource=found;c.Places.SelectedIndex=found.Count==1?0:-1;c.Status.Text=found.Count==1?found[0].Source??"已核对地点":"存在多个地点，请选择准确位置";}catch(OperationCanceledException){throw;}catch(Exception ex){if(!closing)c.Status.Text="地点未核验："+ex.Message;}}
    }
    static int? Minute(string text){if(string.IsNullOrWhiteSpace(text))return null;if(!TimeOnly.TryParseExact(text.Trim(),"HH:mm",out var t))throw new ArgumentException("时间请使用HH:mm格式。");return t.Hour*60+t.Minute;}
