            r.EndDay=null;if(r.Start is {} begin&&r.End is {} end&&r.Day is {} first&&c.EndDay.SelectedDate is {} last){r.EndDay=DateOnly.FromDateTime(last);int span=(r.EndDay.Value.DayNumber-first.DayNumber)*1440+end-begin;if(span<(r.IsReturn?0:1))throw new ArgumentException("结束日期时间必须晚于开始。");r.Duration=span;if(r.LatestEnd is {} deadline)r.LatestEnd=deadline+(r.EndDay.Value.DayNumber-first.DayNumber)*1440;}if(r.Start is null&&r.LatestEnd is null&&r.End is {} automaticDeadline)r.LatestEnd=automaticDeadline;r.ReminderEnabled=c.Reminder.IsChecked==true;r.ReminderLeadMin=int.TryParse(c.Lead.Text,out var lead)?lead:throw new ArgumentException("提醒提前分钟应为0—10080。");
            RepositoryPlanner.Validate(r);var place=c.Chosen??throw new ArgumentException($"请为“{r.Title}”搜索并选择准确地点。");r.Location=place.Name;prepared.Add(new(r,place));
